import React from "react";
import { Link } from "react-router-dom";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff0f6, #e6f7ff, #fff9db)",
        padding: "60px 20px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {/* HERO SECTION */}
      <div
        style={{
          maxWidth: "1200px",
          margin: "auto",
          padding: "80px 50px",
          borderRadius: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          flexWrap: "wrap",
          background: "linear-gradient(135deg, #ffd6ec, #c9f2ff)",
          boxShadow: "0 35px 70px rgba(0,0,0,0.12)",
        }}
      >
        {/* LEFT CONTENT */}
        <div style={{ flex: 1, minWidth: "280px" }}>
          <h1
            style={{
              fontSize: "50px",
              marginBottom: "20px",
              fontWeight: "800",
              background: "linear-gradient(90deg, #ff4f87, #6ec6ff)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            Nanhe Farishte <br /> Kiran Knits
          </h1>

          <p
            style={{
              fontSize: "20px",
              color: "#444",
              marginBottom: "35px",
            }}
          >
            Har bunai mein maa ka pyaar 💖
          </p>

          <Link to="/products">
            <button
              style={{
                background: "linear-gradient(135deg, #ff4f87, #ff85a2)",
                border: "none",
                padding: "16px 50px",
                borderRadius: "50px",
                color: "white",
                fontSize: "18px",
                fontWeight: "600",
                cursor: "pointer",
                transition: "0.3s ease",
                boxShadow: "0 15px 35px rgba(0,0,0,0.2)",
              }}
              onMouseOver={(e) =>
                (e.target.style.transform = "scale(1.08)")
              }
              onMouseOut={(e) =>
                (e.target.style.transform = "scale(1)")
              }
            >
              ✨ Shop Now
            </button>
          </Link>
        </div>

        {/* RIGHT IMAGE SECTION */}
        <div
          style={{
            flex: 1,
            minWidth: "280px",
            display: "flex",
            justifyContent: "center",
            gap: "25px",
            marginTop: "20px",
          }}
        >
          <img
            src="https://images.unsplash.com/photo-1604917877934-07d8d248d396"
            alt="baby sweater"
            style={{
              width: "170px",
              height: "220px",
              borderRadius: "25px",
              objectFit: "cover",
              boxShadow: "0 15px 35px rgba(0,0,0,0.2)",
            }}
          />

          <img
            src="https://images.unsplash.com/photo-1596461404969-9ae70f2830c1"
            alt="baby cap"
            style={{
              width: "170px",
              height: "220px",
              borderRadius: "25px",
              objectFit: "cover",
              boxShadow: "0 15px 35px rgba(0,0,0,0.2)",
            }}
          />
        </div>
      </div>

      {/* CATEGORY SECTION */}
      <div
        style={{
          maxWidth: "1200px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            fontSize: "36px",
            marginBottom: "60px",
            color: "#333",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "50px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard emoji="🧥" title="Sweaters" link="/products?category=Sweater" />
          <CategoryCard emoji="🧦" title="Socks" link="/products?category=Socks" />
          <CategoryCard emoji="🧢" title="Caps" link="/products?category=Cap" />
        </div>
      </div>
    </div>
  );
};

const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "70px 40px",
          borderRadius: "30px",
          width: "240px",
          fontSize: "24px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 25px 50px rgba(0,0,0,0.12)",
          transition: "0.3s ease",
          cursor: "pointer",
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform = "translateY(-15px) scale(1.05)";
          e.currentTarget.style.background =
            "linear-gradient(135deg, #ffe0f0, #e0f7ff)";
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform = "translateY(0) scale(1)";
          e.currentTarget.style.background = "white";
        }}
      >
        <div style={{ fontSize: "45px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

export default Home;
